   "surveyCorner": {
    "title": "Survey Corner",
    "blocks": [
     {
      "h": "Pop quiz: in backstroke, do you move forward or backward?",
      "items": [
       {
        "t": "Forward: 16",
        "n": 1
       },
       {
        "t": "Backward: 15",
        "n": 1
       }
      ],
      "answer": "**The answer: forward!** Just like freestyle, you travel **head first** in backstroke. You're just face-up. Your arms push water toward your feet, so the water pushes you the other way, toward your head. **Fun fact:** it's the only stroke where you **can't see where you're going**. That's why the backstroke flags hang 5 yards from each wall. Know how many strokes you take from the flags to the wall, and you'll never hit your head. 16 of you got it right!"
     }
    ],
    "tip": {
     "h": "First meet checklist",
     "body": [
      "Your first meet is Tuesday! A little planning makes meet day a lot less stressful."
     ],
     "list": [
      "**Pack your bag the night before:** suit, cap, goggles plus a spare, towel, team shirt, water bottle and a snack.",
      "**Bring a full snack**, like a sandwich (or 2) plus fruit or veggies, and eat it 2 to 3 hours before warm-ups so you're fueled up for the meet.",
      "**Hydrate all day.** Bring your water bottle to school and keep sipping.",
      "**Know your events.** Check the heat sheet and listen for your event to be called.",
      "**Cheer for your teammates!** The loudest team on deck is usually the fastest."
     ]
    }
   },
